public class Dig {
    private static String hex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    /* Fingerprint both source contents and movement (mtime) on disk. */
    public static String mill_stamp() {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            List<Path> files = new ArrayList<Path>();
            try (DirectoryStream<Path> ds = Files.newDirectoryStream(Paths.get("/app/slagbin"), "*.java")) {
                for (Path p : ds) files.add(p);
            }
            Collections.sort(files);
            for (Path p : files) {
                md.update(p.getFileName().toString().getBytes(StandardCharsets.UTF_8));
                md.update(Long.toString(Files.getLastModifiedTime(p).toMillis()).getBytes(StandardCharsets.UTF_8));
                md.update(Files.readAllBytes(p));
            }
            return "rel-4:" + hex(md.digest());
        } catch (Exception e) {
            return "invalid";
        }
    }

    public static String mix_id(byte[] sheet) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(sheet);
